/**
 * Open Graph images drawn in code (1200x630): a full-bleed Romandy CTO event
 * photograph under a navy gradient, the strand mark, the page title in
 * Inter Tight (cream) and the brand line in Instrument Serif italic.
 * Two photo variants: "default" and "fde" (see OG_IMAGES, generated by
 * scripts/images/photos.cjs). If the photo is missing the card falls back to
 * cream paper with the mark drawn large on the right, so builds never fail on
 * an absent asset.
 *
 * Every photo card carries a small visible credit ("Photo: a Romandy CTO
 * evening.") so a shared card never reads as a Haystack or FDE Club event.
 * The card is re-encoded as JPEG with sharp: the PNG from next/og is close to
 * 1 MB with a photo behind it, and WhatsApp and some Slack previews drop
 * og:images that large.
 */
import { readFile } from "node:fs/promises"
import { join } from "node:path"
import { ImageResponse } from "next/og"
import sharp from "sharp"
import { STRAND_WIDTH, haystackStrands } from "./formations/strands"
import { OG_IMAGES, type OgVariant } from "./images"

export const OG_SIZE = { width: 1200, height: 630 }
export const OG_CONTENT_TYPE = "image/jpeg"
const PHOTO_CREDIT = "Photo: a Romandy CTO evening."

const PAPER = "#F6F1E7"
const INK = "#1A2136"
const GOLD = "#C29A3E"
const NAVY_RGB = "26,33,54"

const STRANDS = haystackStrands()
const f = (v: number) => (v * 100).toFixed(2)

function Mark({ size, ink = INK }: { size: number; ink?: string }) {
  return (
    <svg width={size} height={size} viewBox="-104 -104 208 208">
      {STRANDS.map((s, i) => (
        <line
          key={i}
          x1={f(s.ax)}
          y1={f(-s.ay)}
          x2={f(s.bx)}
          y2={f(-s.by)}
          stroke={s.gold ? GOLD : ink}
          strokeWidth={STRAND_WIDTH * 100}
          strokeLinecap="round"
        />
      ))}
    </svg>
  )
}

type Fonts = { display: Buffer; serif: Buffer }
let fonts: Promise<Fonts> | undefined
const photos: Partial<Record<OgVariant, Promise<string | null>>> = {}

function loadFonts(): Promise<Fonts> {
  fonts ??= (async () => {
    const root = process.cwd()
    const [display, serif] = await Promise.all([
      readFile(join(root, "src/assets/inter-tight-600.woff")),
      readFile(join(root, "src/assets/instrument-serif-italic.woff")),
    ])
    return { display, serif }
  })()
  return fonts
}

function loadPhoto(variant: OgVariant): Promise<string | null> {
  photos[variant] ??= readFile(join(process.cwd(), OG_IMAGES[variant]))
    .then((b) => `data:image/jpeg;base64,${b.toString("base64")}`)
    .catch(() => null)
  return photos[variant]!
}

/**
 * @param title  Page title, set large on the left.
 * @param variant  Which photo sits behind it: "default" (a packed room of tech
 *   leaders) or "fde" (an engineering talk), both from Romandy CTO evenings.
 */
export async function ogImage(title: string, variant: OgVariant = "default") {
  const [{ display, serif }, photo] = await Promise.all([loadFonts(), loadPhoto(variant)])
  // Page titles are short; Field notes titles can run long, so they step down.
  const titleSize = title.length <= 44 ? 64 : title.length <= 80 ? 52 : 42
  const fg = photo ? PAPER : INK
  const png = new ImageResponse(
    (
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          position: "relative",
          background: photo ? INK : PAPER,
          fontFamily: "Inter Tight",
          color: fg,
        }}
      >
        {photo ? (
          <>
            {/* eslint-disable-next-line @next/next/no-img-element, jsx-a11y/alt-text */}
            <img
              src={photo}
              width={OG_SIZE.width}
              height={OG_SIZE.height}
              style={{ position: "absolute", left: 0, top: 0, width: OG_SIZE.width, height: OG_SIZE.height, objectFit: "cover" }}
            />
            <div
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                width: OG_SIZE.width,
                height: OG_SIZE.height,
                display: "flex",
                backgroundImage: `linear-gradient(90deg, rgba(${NAVY_RGB},0.94) 0%, rgba(${NAVY_RGB},0.86) 42%, rgba(${NAVY_RGB},0.35) 75%, rgba(${NAVY_RGB},0.15) 100%)`,
              }}
            />
          </>
        ) : (
          <div style={{ position: "absolute", right: 90, top: 105, display: "flex" }}>
            <Mark size={420} />
          </div>
        )}

        <div style={{ position: "absolute", left: 64, top: 64, display: "flex", alignItems: "center" }}>
          <Mark size={44} ink={fg} />
          <div style={{ marginLeft: 14, fontSize: 30, letterSpacing: -0.6 }}>Haystack</div>
        </div>

        <div
          style={{
            position: "absolute",
            left: 64,
            top: titleSize === 64 ? 200 : 170,
            width: titleSize === 64 ? 620 : 680,
            display: "flex",
            fontSize: titleSize,
            lineHeight: 1.05,
            letterSpacing: -2,
          }}
        >
          {title}
        </div>

        <div
          style={{
            position: "absolute",
            left: 64,
            bottom: 64,
            display: "flex",
            flexDirection: "column",
            alignItems: "flex-start",
          }}
        >
          <div
            style={{
              fontFamily: "Instrument Serif",
              fontStyle: "italic",
              fontSize: 34,
              lineHeight: 1.1,
              paddingBottom: 6,
              borderBottom: `3px solid ${GOLD}`,
            }}
          >
            Move the needle.
          </div>
        </div>

        {photo && (
          <div
            style={{
              position: "absolute",
              right: 48,
              bottom: 40,
              display: "flex",
              fontFamily: "Instrument Serif",
              fontStyle: "italic",
              fontSize: 18,
              color: `rgba(246,241,231,0.7)`,
            }}
          >
            {PHOTO_CREDIT}
          </div>
        )}
      </div>
    ),
    {
      ...OG_SIZE,
      fonts: [
        { name: "Inter Tight", data: display, weight: 600, style: "normal" },
        { name: "Instrument Serif", data: serif, weight: 400, style: "italic" },
      ],
    },
  )
  const jpeg = await sharp(Buffer.from(await png.arrayBuffer()))
    .jpeg({ quality: 80, mozjpeg: true })
    .toBuffer()
  return new Response(new Uint8Array(jpeg), {
    headers: { "Content-Type": OG_CONTENT_TYPE, "Cache-Control": "public, max-age=31536000, immutable" },
  })
}
